        this.bezierVertex(midX, midY, midX, midY, x2, y2);
      } else {
        this.vertex(x2, y2);
      }
      this.endShape();
    };

    const origEllipse = p5.prototype.ellipse;
    p5.prototype.ellipse = function(x, y, w, h) {
