let spins = [];
let particles = [];
let nx = 7;
let ny = 7;
let nz = 1; // 2D let Model plane for topological vortices
let spacing = 110;
let r = 25;
let numParticles = 800;

class SpinParticle {
  constructor(ix, iy, iz, x, y, z) {
    this.ix = ix;
    this.iy = iy;
    this.iz = iz;
    this.pos = createVector(x, y, z);
    this.theta = random(0, TWO_PI);
    this.S = createVector(cos(this.theta), sin(this.theta), 0);
    this.omega = random(-0.8, 0.8);
  }

  update(dt, grid, J, alpha) {
    // 變種特點: XY 轉子相位交互作用 (Kuramoto / let Model)
    let sumSin = 0;
    let dirs = [[-1, 0, 0], [1, 0, 0], [0, -1, 0], [0, 1, 0]];
    for (let d of dirs) {
      let nix = this.ix + d[0];
      let niy = this.iy + d[1];
      if (nix >= 0 && nix < nx && niy >= 0 && niy < ny) {
        let idx = nix + niy * nx;
        let other = grid[idx];
        sumSin += sin(other.theta - this.theta);
      }
    }

    // let update equation
    let beatVal = window.beatEnergy || 0.0;
    let drive = (window.audioLow || 0.5) * 2.0 * cos(this.theta + frameCount * 0.05);
    this.theta += (this.omega + J * sumSin + drive) * dt;

    this.S.set(cos(this.theta), sin(this.theta), 0);
  }

  draw() {
    push();
    translate(this.pos.x, this.pos.y, this.pos.z);

    // 2D let circle
    colorMode(HSB, 360, 100, 100, 1.0);
    noFill();
    stroke(45, 80, 95, 0.07); // let amber ring
    strokeWeight(0.5);
    ellipse(0, 0, r * 2, r * 2);

    // let angle to golden/amber let color space (15 to 65)
    let hueVal = map(sin(this.theta), -1, 1, 15, 60);
    stroke(hueVal, 90, 95);
    strokeWeight(1.8);
    line(0, 0, 0, this.S.x * r, this.S.y * r, 0);

    noStroke();
    fill(hueVal, 90, 95, 0.75);
    ellipse(this.S.x * r, this.S.y * r, 5, 5);
    pop();
  }
}

class FlowParticle {
  constructor() {
    this.reset();
  }

  reset() {
    let wRange = (nx * spacing) / 2 + 50;
    let hRange = (ny * spacing) / 2 + 50;
    this.pos = createVector(random(-wRange, wRange), random(-hRange, hRange), random(-60, 60));
    this.prevPos = this.pos.copy();
    this.vel = createVector(0, 0, 0);
    this.life = random(60, 140);
    this.maxLife = this.life;
  }

  update(grid, J) {
    this.prevPos.set(this.pos);

    // 變種特點: 粒子會圍繞著轉子形成渦旋運動 (let Field)
    let force = getVortexForce(this.pos);

    let nScale = 0.0035;
    let nX = noise(this.pos.x * nScale, this.pos.y * nScale, frameCount * 0.006) - 0.5;
    let nY = noise(this.pos.y * nScale, this.pos.x * nScale, frameCount * 0.006) - 0.5;
    let noiseForce = createVector(nX, nY, 0).mult(0.28);

    let beatVal = window.beatEnergy || 0;
    let combinedForce = p5.Vector.add(p5.Vector.mult(force, 0.75 + beatVal * 1.0), noiseForce);

    this.vel.add(combinedForce);
    this.vel.limit(2.5 + (window.audioLow || 0.5) * 5.0 + beatVal * 4.0);
    this.pos.add(this.vel);
    this.life--;

    let wLimit = (nx * spacing) / 2 + 100;
    let hLimit = (ny * spacing) / 2 + 100;
    if (this.life <= 0 || abs(this.pos.x) > wLimit || abs(this.pos.y) > hLimit) {
      this.reset();
    }
  }

  draw(colHex) {
    let alphaVal = map(this.life, 0, this.maxLife, 0.0, 0.1);
    if (window.beatEnergy > 0.5) alphaVal *= 1.6;

    colorMode(RGB, 255, 255, 255, 1.0);
    let c = color(colHex || "#ffa500");
    stroke(red(c), green(c), blue(c), alphaVal);
    strokeWeight(0.9);
    line(this.pos.x, this.pos.y, this.pos.z, this.prevPos.x, this.prevPos.y, this.prevPos.z);
  }
}

function getVortexForce(pos) {
  let xStart = -((nx - 1) * spacing) / 2;
  let yStart = -((ny - 1) * spacing) / 2;
  let ix = Math.round((pos.x - xStart) / spacing);
  let iy = Math.round((pos.y - yStart) / spacing);
  if (ix >= 0 && ix < nx && iy >= 0 && iy < ny) {
    let idx = ix + iy * nx;
    let spinS = spins[idx].S;
    // 向量旋轉 90 度形成切向渦旋力 field
    return createVector(-spinS.y, spinS.x, 0);
  }
  return createVector(0, 0, 0);
}

function setup() {
  createCanvas(1280, 720, WEBGL);
  colorMode(HSB, 360, 100, 100, 1.0);

  let xStart = -((nx - 1) * spacing) / 2;
  let yStart = -((ny - 1) * spacing) / 2;

  for (let iy = 0; iy < ny; iy++) {
    for (let ix = 0; ix < nx; ix++) {
      let x = xStart + ix * spacing;
      let y = yStart + iy * spacing;
      spins.push(new SpinParticle(ix, iy, 0, x, y, 0));
    }
  }
  for (let i = 0; i < numParticles; i++) {
    particles.push(new FlowParticle());
  }
  background(8, 6, 4);
}

function draw() {
  push();
  resetMatrix();
  noStroke();
  colorMode(RGB, 255, 255, 255, 1.0);
  fill(8, 6, 4, 0.08);
  rect(-width/2, -height/2, width, height);
  pop();

  let dt = 0.06;
  let baseJ = 0.25;
  let audioVal = window.audioLow || 0.5;
  let beatVal = window.beatEnergy || 0.0;
  let weightScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;
  let J = (baseJ + audioVal * 1.8 + beatVal * 3.8) * weightScale;

  for (let s of spins) {
    s.update(dt, spins, J, 0.1);
  }
  for (let p of particles) {
    p.update(spins, J);
  }

  let rotX = 0.35 + sin(frameCount * 0.0008) * 0.08;
  let rotY = cos(frameCount * 0.0006) * 0.12;
  let rotZ = frameCount * 0.0018 + beatVal * 0.01;

  push();
  rotateX(rotX);
  rotateY(rotY);
  rotateZ(rotZ);

  drawSyncConnections();
  for (let s of spins) {
    s.draw();
  }

  let chordCol = window.currentChordColor || "#ffa500";
  for (let p of particles) {
    p.draw(chordCol);
  }
  pop();
}

function drawSyncConnections() {
  let chordCol = window.currentChordColor || "#ffa500";
  colorMode(RGB, 255, 255, 255, 1.0);
  let c = color(chordCol);
  for (let s of spins) {
    let neighbors = [[1, 0, 0], [0, 1, 0]];
    for (let n of neighbors) {
      let nix = s.ix + n[0];
      let niy = s.iy + n[1];
      if (nix < nx && niy < ny) {
        let nidx = nix + niy * nx;
        let other = spins[nidx];
        let diff = abs(s.theta - other.theta) % TWO_PI;
        if (diff > PI) diff = TWO_PI - diff;
        if (diff < 0.35) { // 相位差小於 20 度視為同步
          let strength = map(diff, 0, 0.35, 1.0, 0.0);
          let beatVal = window.beatEnergy || 0.0;
          let alphaVal = strength * (0.16 + beatVal * 0.36);
          stroke(red(c), green(c), blue(c), alphaVal);
          strokeWeight(0.5 + strength * 1.5 + beatVal * 1.2);
          line(s.pos.x, s.pos.y, 0, other.pos.x, other.pos.y, 0);
        }
      }
    }
  }
}

